package com.eventhub.dto; import com.eventhub.entity.Feedback; import java.time.Instant; public record FeedbackResponse(Long id,Long eventId,Long userId,String userName,int rating,String comment,Instant createdAt){public static FeedbackResponse from(Feedback f){return new FeedbackResponse(f.getId(),f.getEvent().getId(),f.getUser().getId(),f.getUser().getFirstName()+" "+f.getUser().getLastName(),f.getRating(),f.getComment(),f.getCreatedAt());}}
